import { getList as _getList } from "@/api/treeManager/cmdbres";
import arrtMapping from "./components/tree/arrtMapping.vue";
import CmdbResAddEdit from "@/views/cmdb/components/treeManage/components/cmdbres/addedit.vue";
import PzsxAddEdit from "@/views/cmdb/components/treeManage/components/pzsx/addedit.vue";
//成本中心页面
export default {
  name: 'tabCmdbRes',
  components: {
    PzsxAddEdit: PzsxAddEdit,
    CmdbResAddEdit: CmdbResAddEdit,
    arrtMapping: arrtMapping
  },
  data: function data() {
    return {
      tableloading: false,
      queryParams: {},
      page: {
        currentPage: 1,
        pageSize: 20,
        total: 0
      },
      tableData: null,
      showAddEdit: false,
      fromValue: null,
      type: null,
      showArrt: false,
      ciId: '',
      ciName: '',
      ciLabel: ''
    };
  },
  mounted: function mounted() {
    this.page = {
      currentPage: 1,
      pageSize: 20,
      total: 0
    };
    this.getList();
  },
  methods: {
    getList: function getList() {
      var _this = this;
      this.tableloading = true;
      _getList(this.page.currentPage, this.page.pageSize, this.queryParams).then(function (res) {
        var data = res.data;
        _this.page.total = data.total;
        _this.tableData = data.records;
        _this.tableloading = false;
      });
    },
    handelAdd: function handelAdd() {
      this.type = 'add';
      this.showAddEdit = true;
    },
    handleEdit: function handleEdit(row) {
      this.type = 'edit';
      this.showAddEdit = true;
      this.fromValue = row;
    },
    handelDelete: function handelDelete(id) {
      var _this2 = this;
      if (id) {
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(function () {
          return remove(id);
        }).then(function () {
          _this2.getList();
          _this2.$message({
            type: "success",
            message: "删除成功!"
          });
        });
      } else {
        if (this.$refs.table.selection.length === 0) {
          this.$message.warning("请选择至少一条数据");
          return;
        }
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(function () {
          var ids = _this2.$refs.table.selection.map(function (item, index) {
            return item.id;
          }).join(',');
          return remove(ids);
        }).then(function () {
          _this2.getList();
          _this2.$message({
            type: "success",
            message: "操作成功!"
          });
        });
      }
    },
    handleYs: function handleYs(row) {
      this.showArrt = true;
      this.ciId = row.selectCiId;
      this.ciName = row.selectCiName;
      this.ciLabel = row.ciLabel;
    },
    getIsExistCascadeText: function getIsExistCascadeText(isExistCascadeText) {
      if (isExistCascadeText == '0') {
        return '否';
      } else if (isExistCascadeText == '1') {
        return '是';
      }
      return null;
    },
    Nindex: function Nindex(index) {
      return index + 1 + (this.page.currentPage - 1) * this.page.pageSize;
    },
    reset: function reset() {
      this.queryParams = {};
      this.page = {
        currentPage: 1,
        pageSize: 20,
        total: 0
      };
      this.getList();
    }
  }
};
